	@Test
	void heldStandaloneTermIteratorRetainsItsIndexUntilClose() throws Exception {
		StoreProperties properties = new StoreProperties(directory.toFile());
		seed(properties, 20);
		try (ClosingValueStore initial = open(properties, "spoc,cspo,posc")) {
			initial.startIndexRebuildAfterStoreInitialization();
			assertTrue(initial.awaitIndexRebuild(20, TimeUnit.SECONDS), initial.indexRebuildStatus());
		}
		try (ClosingValueStore store = open(properties, "spoc,cspo,ospc")) {
			CountDownLatch cleanupDecision = new CountDownLatch(1);
			store.setTermIndexMaintenanceObserver(phase -> {
				if (phase.startsWith("cleanup-")) {
					cleanupDecision.countDown();
				}
			});
			int count = 0;
			try (RecordIterator held = store.getTripleTerms(-1,
					store.getId(VF.createIRI("urn:term-background:predicate")), -1)) {
				assertTrue(held.next() != null);
				count++;
				store.startIndexRebuildAfterStoreInitialization();
				assertTrue(cleanupDecision.await(10, TimeUnit.SECONDS));
				while (held.next() != null) {
					count++;
				}
			}
			assertEquals(20, count, "background cleanup must retain the tree chosen by an open term iterator");
			assertTrue(store.awaitIndexRebuild(20, TimeUnit.SECONDS), store.indexRebuildStatus());
		}
	}

	@Test
	void mapGrowthWaitsForTheAdmittedBackgroundTermWriter() throws Exception {
		StoreProperties properties = new StoreProperties(directory.toFile());
		seed(properties, 20);
		try (ClosingValueStore store = open(properties, TARGET)) {
			CountDownLatch writerActive = new CountDownLatch(1);
			CountDownLatch releaseWriter = new CountDownLatch(1);
			store.setTermIndexMaintenanceObserver(phase -> {
				if (phase.equals("dual-write-registered")) {
					writerActive.countDown();
					await(releaseWriter);
				}
			});
			store.startIndexRebuildAfterStoreInitialization();
			assertTrue(writerActive.await(10, TimeUnit.SECONDS));
			CompletableFuture<Boolean> result = new CompletableFuture<>();
			Thread growth = new Thread(() -> {
				try {
					result.complete(store.growMapForEstimatedWrite(store.mapSizeBytes(), null));
				} catch (Throwable failure) {
					result.completeExceptionally(failure);
				}
			}, "term-maintenance-growth-regression");
			growth.start();
			try {
				// Observe the actual blocked admission or terminal return, rather than guessing a scheduling delay.
				long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(10);
				while (!result.isDone() && growth.getState() != Thread.State.WAITING && System.nanoTime() < deadline) {
					Thread.onSpinWait();
				}
				releaseWriter.countDown();
				assertTrue(result.get(10, TimeUnit.SECONDS),
						"a foreign maintenance writer cannot turn a required growth into a no-progress return");
			} finally {
				releaseWriter.countDown();
				growth.join(TimeUnit.SECONDS.toMillis(10));
			}
			assertTrue(store.awaitIndexRebuild(20, TimeUnit.SECONDS), store.indexRebuildStatus());
		}
	}

	@Test
	void stagingCopyRechecksDeletedRowsAndDualWritesInsertionsBehindProgress() throws Exception {
		StoreProperties properties = new StoreProperties(directory.toFile());
		List<TripleTerm> terms = seed(properties, 3000);
		try (ClosingValueStore store = open(properties, TARGET)) {
			CountDownLatch copiedRead = new CountDownLatch(1);
			CountDownLatch release = new CountDownLatch(1);
			AtomicBoolean once = new AtomicBoolean();
			store.setTermIndexMaintenanceObserver(phase -> {
				if (phase.equals("copy-read") && once.compareAndSet(false, true)) {
					copiedRead.countDown();
					await(release);
				}
			});
			store.startIndexRebuildAfterStoreInitialization();
			try {
				assertTrue(copiedRead.await(10, TimeUnit.SECONDS));
				store.startTransaction(true);
				store.gcIds(Set.of(store.getId(terms.get(0))), new HashSet<>());
				TripleTerm inserted = VF.createTripleTerm(terms.get(0).getSubject(), terms.get(0).getPredicate(),
						VF.createLiteral("inserted behind copy continuation"));
				long insertedId = store.storeValue(inserted);
				store.commit();
				release.countDown();
				assertTrue(store.awaitIndexRebuild(20, TimeUnit.SECONDS), store.indexRebuildStatus());
				assertEquals(LmdbValue.UNKNOWN_ID, store.getId(terms.get(0)));
				assertEquals(insertedId, store.getId(inserted));
				assertEquals(3000, termCount(store));
				assertTrue(store.hasTrustedReferenceCounts());
			} finally {
				release.countDown();
			}
		}
	}

	@Test
	void stageCopyDoesNotCountDependenciesOrResurrectRetiredCspoPayloads() throws Exception {
		StoreProperties properties = new StoreProperties(directory.toFile());
		List<TripleTerm> terms = seed(properties, 20);
		long dependency;
		long retiredId;
		try (ClosingValueStore store = open(properties, "spoc,cspo")) {
			dependency = store.getId(terms.get(1).getPredicate());
			retiredId = store.getId(terms.get(0));
			store.startTransaction(true);
			store.gcIds(Set.of(retiredId), new HashSet<>());
			store.commit();
			assertEquals(terms.get(0), store.getValue(retiredId), "retired CSPO payload remains resolvable");
		}
		byte[] before = LmdbCompatibilityFixtures.nativeGet(directory, "ref_counts",
				LmdbCompatibilityFixtures.idKey(dependency));
		try (ClosingValueStore store = open(properties, TARGET)) {
			store.startIndexRebuildAfterStoreInitialization();
			assertTrue(store.awaitIndexRebuild(20, TimeUnit.SECONDS), store.indexRebuildStatus());
			assertEquals(LmdbValue.UNKNOWN_ID, store.getId(terms.get(0)));
			assertEquals(19, termCount(store));
		}
		assertArrayEquals(before, LmdbCompatibilityFixtures.nativeGet(directory, "ref_counts",
				LmdbCompatibilityFixtures.idKey(dependency)));
		assertEquals(19, LmdbCompatibilityFixtures.nativeValueEntryCount(directory, "term-poscterm-posc"));
	}

	@Test
	void committedCopyProgressResumesAfterCrashImageAndKeepsOldReadersUsable() throws Exception {
		StoreProperties properties = new StoreProperties(directory.toFile());
		List<TripleTerm> terms = seed(properties, 3000);
		Path crashed = directory.resolve("crashed/values");
		try (ClosingValueStore store = open(properties, TARGET)) {
			AtomicInteger reads = new AtomicInteger();
			CountDownLatch secondRead = new CountDownLatch(1);
			CountDownLatch release = new CountDownLatch(1);
			store.setTermIndexMaintenanceObserver(phase -> {
				if (phase.equals("copy-read") && reads.incrementAndGet() == 2) {
					secondRead.countDown();
					await(release);
				}
			});
			try (var oldReader = store.getTxnManager().createReadTxnUntracked()) {
				store.startIndexRebuildAfterStoreInitialization();
				try {
					assertTrue(secondRead.await(10, TimeUnit.SECONDS));
					Files.createDirectories(crashed);
					Files.copy(directory.resolve("values/data.mdb"), crashed.resolve("data.mdb"));
					release.countDown();
					assertEquals(3000, termCount(store, oldReader));
				} finally {
					release.countDown();
				}
			}
			assertTrue(store.awaitIndexRebuild(20, TimeUnit.SECONDS), store.indexRebuildStatus());
		}
		StoreProperties crashProperties = new StoreProperties(directory.resolve("crashed").toFile());
		try (ClosingValueStore store = new ClosingValueStore(crashed.toFile(), crashProperties,
				new LmdbStoreConfig().setTripleTermIndexes(TARGET))) {
			assertEquals(Set.of("spoc", "cspo"),
					TripleIndex.parseIndexSpecList(crashProperties.getTripleTermIndexes()));
			store.startIndexRebuildAfterStoreInitialization();
			assertTrue(store.awaitIndexRebuild(20, TimeUnit.SECONDS), store.indexRebuildStatus());
			assertEquals(3000, termCount(store));
			assertTrue(store.getId(terms.get(100)) != LmdbValue.UNKNOWN_ID);
		}
	}

	@Test
	void queuedRequestsCoalesceAndRollbackDoesNotLeakIntoStaging() throws Exception {
		StoreProperties properties = new StoreProperties(directory.toFile());
		seed(properties, 30);
		try (ClosingValueStore store = open(properties, TARGET)) {
			store.requestTermIndexRebuild("spoc,cspo,psoc");
			store.startTransaction(true);
			TripleTerm rolledBack = VF.createTripleTerm(VF.createIRI("urn:term-background:rollback"),
					VF.createIRI("urn:term-background:predicate"), VF.createLiteral("rollback"));
			store.storeValue(rolledBack);
			store.rollback();
			store.startIndexRebuildAfterStoreInitialization();
			assertTrue(store.awaitIndexRebuild(20, TimeUnit.SECONDS), store.indexRebuildStatus());
			assertEquals(Set.of("spoc", "cspo", "psoc"),
					TripleIndex.parseIndexSpecList(properties.getTripleTermIndexes()));
			assertEquals(30, termCount(store));
			assertEquals(LmdbValue.UNKNOWN_ID, store.getId(rolledBack));
		}
	}

	private List<TripleTerm> seed(StoreProperties properties, int count) throws IOException {
		List<TripleTerm> terms = new ArrayList<>();
		try (ClosingValueStore store = open(properties, "spoc,cspo")) {
			store.startTransaction(true);
			for (int i = 0; i < count; i++) {
				TripleTerm term = VF.createTripleTerm(VF.createIRI("urn:term-background:s:" + i),
						VF.createIRI("urn:term-background:predicate"), VF.createLiteral("object " + i));
				terms.add(term);
				store.storeValue(term);
			}
			store.commit();
		}
		return terms;
	}

	private ClosingValueStore open(StoreProperties properties, String indexes) throws IOException {
		return new ClosingValueStore(directory.resolve("values").toFile(), properties,
				new LmdbStoreConfig().setTripleTermIndexes(indexes).setValueDBSize(32L * 1024 * 1024));
	}

