	private static int termCount(ValueStore store) throws IOException {
		try (var reader = store.getTxnManager().createReadTxnUntracked()) {
			return termCount(store, reader);
		}
	}

	private static int termCount(ValueStore store, TxnManager.Txn reader) throws IOException {
		int count = 0;
		try (RecordIterator records = store.getTripleTerms(reader, -1, -1, -1)) {
			while (records.next() != null) {
				count++;
			}
		}
		return count;
	}

	private static void await(CountDownLatch latch) {
		try {
			assertTrue(latch.await(20, TimeUnit.SECONDS));
		} catch (InterruptedException interrupted) {
			Thread.currentThread().interrupt();
		}
	}

	private static final class ClosingValueStore extends ValueStore implements AutoCloseable {
		ClosingValueStore(File directory, StoreProperties properties, LmdbStoreConfig config) throws IOException {
			super(directory, properties, config);
		}
	}
